parameters.text:
=Simulate a realistic outbound telephone conversation.

CALLER
Business: {{ $json.body.business_name }}
Service: {{ $json.body.service }}
Reason: {{ $json.body.call_reason }}

CONTACT
Name: {{ $json.body.name }}
Phone: {{ $json.body.phone }}
Email: {{ $json.body.email }}
Context: {{ $json.body.context }}
Preferred language: {{ $json.body.preferred_language }}

Create a natural, varied conversation between:

1. A professional AI calling assistant representing {{ $json.body.business_name }}.
2. {{ $json.body.name }}, the contact receiving the call.

The assistant is calling about {{ $json.body.service }}.

Guidelines:
- The contact should ask realistic questions, express doubts, or raise concerns based on the provided context.
- The decision should feel believable: sometimes interested, sometimes hesitant, sometimes not interested.
- The assistant should respond professionally but adapt tone and detail to the contact’s reactions.
- The conversation must be conducted in {{ $json.body.preferred_language }}.
- Allow outcomes to vary (interested, not interested, neutral) depending on the flow of the dialogue.
- Include natural pauses, clarifications, or follow-up questions to make the exchange more authentic.

Return the result according to the required structured output format.

parameters.inputSchema:
{
  "title": "CallOutcome",
  "type": "object",
  "properties": {
    "call_status": {
      "type": "string",
      "enum": ["completed", "failed", "in_progress"]
    },
    "outcome": {
      "type": "string",
      "enum": ["interested", "not_interested", "neutral"]
    },
    "interest_level": {
      "type": "string",
      "enum": ["low", "medium", "high"]
    },
    "callback_time": {
      "type": ["string", "null"],
      "description": "Date and time for callback if scheduled"
    },
    "phone": {
      "type": "string"
    },
    "email": {
      "type": "string"
    },
    "summary": {
      "type": "string"
    },
    "next_action": {
      "type": "string",
      "enum": ["send_information", "schedule_callback", "end_conversation"]
    },
    "transcript": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "speaker": {
            "type": "string",
            "enum": ["assistant", "contact"]
          },
          "message": {
            "type": "string"
          }
        },
        "required": ["speaker", "message"]
      }
    }
  },
  "required": [
    "call_status",
    "outcome",
    "interest_level",
    "phone",
    "summary",
    "next_action",
    "transcript"
  ]
}

parameters.jsCode:
const item = $input.first().json;
const fallback = {
  classifier: {
    outcome: 'unknown',
    interest_level: 'none',
    confidence: 0,
    fallback_used: true,
    agent_error: item.error ? String(item.error) : 'classifier returned invalid output'
  }
};
const o = item.output;
if (!o || typeof o !== 'object') return [{ json: fallback }];
const validLevels = ['high', 'medium', 'low', 'none'];
const level = String(o.interest_level || '').toLowerCase();
if (!o.outcome || !validLevels.includes(level)) return [{ json: fallback }];
return [{ json: { classifier: { outcome: String(o.outcome), interest_level: level, confidence: typeof o.confidence === 'number' ? o.confidence : 0.5, fallback_used: false } } }];

const item = $input.first().json;
const src = $('Outbound call simulation').first().json.output || {};
const contact = $('Prepare contact Data').first().json.body || {};
const fallback = {
  extractor: {
    contact_name: contact.name || null,
    contact_email: contact.email || null,
    phone_number: contact.phone || src.phone || null,
    callback_time: null,
    requested_information: null,
    product_or_service: contact.service || null,
    questions_or_concerns: [],
    summary: src.summary || 'Call completed; extraction failed, using call summary.',
    fallback_used: true,
    agent_error: item.error ? String(item.error) : 'extractor returned invalid output'
  }
};
const o = item.output;
if (!o || typeof o !== 'object' || (!o.contact_name && !o.summary)) return [{ json: fallback }];
return [{ json: { extractor: {
  contact_name: o.contact_name ?? null,
  contact_email: o.contact_email ?? null,
  phone_number: o.phone_number ?? contact.phone ?? null,
  callback_time: o.callback_time ?? null,
  requested_information: o.requested_information ?? null,
  product_or_service: o.product_or_service ?? contact.service ?? null,
  questions_or_concerns: Array.isArray(o.questions_or_concerns) ? o.questions_or_concerns : [],
  summary: o.summary ?? src.summary ?? null,
  fallback_used: false
} } }];

parameters.text:
=Analyze the following results and determine the next action.

CLASSIFIER:
{{ $json.classifier?.toJsonString() ?? "unavailable" }}

EXTRACTOR:
{{ $json.extractor?.toJsonString() ?? "unavailable" }}

Note: if a result contains fallback_used: true, that agent output was invalid and fallback defaults were used.

parameters.jsCode:
const item = $input.first().json;
const validActions = ['send_information', 'schedule_callback', 'follow_up', 'escalate', 'no_action'];
const validPriorities = ['low', 'medium', 'high'];
const o = item.output;
if (!o || typeof o !== 'object' || !validActions.includes(o.next_action)) {
  return [{ json: { output: {
    next_action: 'follow_up',
    priority: 'medium',
    reason: 'Reasoner output unavailable or invalid; defaulting to follow_up.',
    fallback_used: true,
    agent_error: item.error ? String(item.error) : 'reasoner returned invalid output'
  } } }];
}
return [{ json: { output: {
  next_action: o.next_action,
  priority: validPriorities.includes(o.priority) ? o.priority : 'medium',
  reason: o.reason || 'No reason provided.',
  fallback_used: false
} } }];

parameters.text:
=Compose the final response using the following information.

TRANSCRIPT:
{{ $('Outbound call simulation').item.json.output.transcript?.toJsonString() ?? "No transcript available" }}

EXTRACTED INFORMATION:
{{ $('Validate Extractor Output').item.json.extractor?.toJsonString() ?? "unavailable" }}
REASONER DECISION:
{{ $json.output?.toJsonString() ?? "unavailable; treat next_action as follow_up" }}

parameters.jsCode:
const safe = (name) => {
  try {
    const j = $(name).first().json;
    return (j && typeof j === 'object' && !j.error) ? (j.output ?? j) : null;
  } catch (e) { return null; }
};

const callResult = safe('Outbound call simulation') || {};
const contact = $('Prepare contact Data').first().json.body || {};
const classifierRaw = safe('Classifier Agent - Call Outcome') || {};
const reasonerRaw = safe('Reasoner Agent - Next Action') || {};
const composerRaw = $input.first().json || {};
const composer = (composerRaw && typeof composerRaw === 'object' && !composerRaw.error) ? (composerRaw.output || {}) : {};

// Normalized extractor output (already validated by 'Edit Fields'); fall back to raw agent output or contact data
const normalized = safe('Validate Extractor Output') || {};
const extractorRaw = safe('Extractor Agent - Call Details') || {};
const extractor = normalized.extractor || (Object.keys(extractorRaw).length ? extractorRaw : {
  contact_name: contact.name ?? null,
  contact_email: contact.email ?? null,
  phone_number: contact.phone ?? callResult.phone ?? null,
  callback_time: null,
  summary: callResult.summary ?? 'No reliable summary available.',
  fallback_used: true
});

const classifier = (classifierRaw.outcome || classifierRaw.interest_level) ? classifierRaw : {
  outcome: 'uncertain',
  interest_level: 'none',
  confidence: 0,
  fallback_used: true
};

const reasoner = reasonerRaw.next_action ? reasonerRaw : {
  next_action: 'follow_up',
  priority: 'medium',
  reason: 'The appropriate action could not be determined reliably.',
  fallback_used: true
};

return [
  {
    json: {
      call_status: callResult.call_status ?? 'completed',

      outcome: classifier.outcome ?? 'uncertain',

      interest_level: classifier.interest_level ?? 'none',

      callback_time:
        extractor.callback_time ??
        callResult.callback_time ??
        null,

      summary:
        extractor.summary ??
        callResult.summary ??
        'No reliable summary available.',

      next_action:
        reasoner.next_action ?? 'follow_up',

      transcript: callResult.transcript ?? [],

      classification: {
        outcome: classifier.outcome ?? 'uncertain',
        interest_level: classifier.interest_level ?? 'none',
        confidence: classifier.confidence ?? 0
      },

      extraction: extractor,

      decision: {
        next_action: reasoner.next_action ?? 'follow_up',
        priority: reasoner.priority ?? 'medium',
        reason:
          reasoner.reason ??
          'The appropriate action could not be determined reliably.'
      },

      response: {
        message:
          composer.response ??
          'Thank you for your interest. We will follow up regarding your request.',
        follow_up_required:
          composer.follow_up_required ?? true
      }
    }
  }
];

